<?php require_once __DIR__.'/../includes/auth.php';$pageTitle='Suppliers';$base='/shop-inventory-management';$q=trim($_GET['q']??'');$sql='SELECT s.*,COUNT(p.id) product_count FROM suppliers s LEFT JOIN products p ON p.supplier_id=s.id';$args=[];if($q!==''){$sql.=' WHERE s.name LIKE ?';$args[]='%'.$q.'%';}$sql.=' GROUP BY s.id ORDER BY s.name';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Suppliers</h1><p>Maintain supplier contacts and product links.</p></div><a class="btn primary" href="create.php">＋ Add supplier</a></div><div class="panel"><form class="toolbar" method="get"><input name="q" placeholder="Search supplier name…" value="<?=e($q)?>"><button class="btn">Search</button><a class="btn" href="index.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Phone</th><th>Email</th><th>Products</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No suppliers found.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small class="subline"><?=e($r['address']??'')?></small></td><td><?=e($r['phone']?:'—')?></td><td><?=e($r['email']?:'—')?></td><td><?=$r['product_count']?></td><td class="actions"><a class="btn small" href="view.php?id=<?=$r['id']?>">View</a><a class="btn small" href="edit.php?id=<?=$r['id']?>">Edit</a><form method="post" action="delete.php" class="inline-form" data-confirm="Delete this supplier? Only suppliers without linked products can be deleted."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small danger">Delete</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
